1	package com.example.starter.cutover;
2	
3	import static com.example.starter.cutover.CutoverFixtures.DEVICE_SW1;
4	import static com.example.starter.cutover.CutoverFixtures.steps;
5	import static org.assertj.core.api.Assertions.assertThat;
6	
7	import com.example.starter.cutover.dto.ActionResult;
8	import com.example.starter.cutover.dto.ApproveRequest;
9	import com.example.starter.cutover.dto.CreateCutoverRequest;
10	import com.example.starter.cutover.dto.ExpireCheckRequest;
11	import com.example.starter.cutover.dto.SealRequest;
12	import com.example.starter.cutover.dto.StartExecutionRequest;
13	import com.example.starter.cutover.dto.StepReportRequest;
14	import com.example.starter.cutover.model.CutoverEventPO;
15	import com.example.starter.cutover.repo.CutoverRepository;
16	import com.example.starter.cutover.service.CutoverService;
17	import java.time.LocalDateTime;
18	import java.util.List;
19	import java.util.concurrent.CountDownLatch;
20	import java.util.concurrent.ExecutorService;
21	import java.util.concurrent.Executors;
22	import java.util.concurrent.Future;
23	import java.util.concurrent.TimeUnit;
24	import org.junit.jupiter.api.BeforeEach;
25	import org.junit.jupiter.api.DisplayName;
26	import org.junit.jupiter.api.Test;
27	import org.springframework.beans.factory.annotation.Autowired;
28	import org.springframework.boot.test.context.SpringBootTest;
29	import org.springframework.jdbc.core.JdbcTemplate;
30	
31	/**
32	 * H2 真实并发与事务边界测试：行锁 FOR UPDATE 串行化下的唯一终态与幂等。
33	 */
34	@SpringBootTest
35	class CutoverConcurrencyTest {
36	
37	    private static final LocalDateTime BASE = LocalDateTime.of(2026, 11, 1, 2, 0);
38	
39	    @Autowired
40	    private CutoverService service;
41	    @Autowired
42	    private CutoverRepository repo;
43	    @Autowired
44	    private JdbcTemplate jdbc;
45	
46	    @BeforeEach
47	    void clean() {
48	        jdbc.update("DELETE FROM cutover_event");
49	        jdbc.update("DELETE FROM cutover_step");
50	        jdbc.update("DELETE FROM cutover_request");
51	    }
52	
53	    private void prepareExecuting(String id, LocalDateTime s, LocalDateTime e, Priority p) {
54	        service.create(new CreateCutoverRequest(id, "割接-" + id, DEVICE_SW1, p, s, e,
55	                steps("停流量", "NORMAL", "配置下发", "NORMAL",
56	                        "关键验证", "CRITICAL", "硬性检查", "HARDCHECK")));
57	        service.analyze(id);
58	        service.approve(new ApproveRequest("ap-" + id, id, true, null));
59	        service.startExecution(new StartExecutionRequest("ex-" + id, id, s));
60	    }
61	
62	    @Test
63	    @DisplayName("回退与验证通过并发：终态唯一，不得既回退又封板（真实线程+行锁）")
64	    void rollbackAndVerifyRaceHasSingleTerminal() throws Exception {
65	        LocalDateTime end = BASE.plusHours(1);
66	        String id = "R-RACE-1";
67	        prepareExecuting(id, BASE, end, Priority.HIGH);
68	        // 前三步在窗口内完成，仅剩 seq4(HARDCHECK) 在窗口终点回报
69	        service.report(new StepReportRequest("c-r1", id, 1, true, BASE.plusMinutes(40), null));
70	        service.report(new StepReportRequest("c-r2", id, 2, true, BASE.plusMinutes(45), null));
71	        service.report(new StepReportRequest("c-r3", id, 3, true, BASE.plusMinutes(50), null));
72	
73	        ExecutorService pool = Executors.newFixedThreadPool(2);
74	        CountDownLatch start = new CountDownLatch(1);
75	        try {
76	            // A：恰在窗口终点回报最后一步成功 -> VERIFIED
77	            Future<Object> fa = pool.submit(() -> {
78	                start.await();
79	                return service.report(new StepReportRequest(
80	                        "c-r4-ok", id, 4, true, end, null));
81	            });
82	            // B：窗口结束时刻巡检（恰终点），若仍有未完成步骤 -> WINDOW_EXPIRED 强制回退
83	            Future<Object> fb = pool.submit(() -> {
84	                start.await();
85	                return service.expireCheck(new ExpireCheckRequest("c-exp", id, end));
86	            });
87	            start.countDown();
88	
89	            // 竞态失败方可能抛业务异常（回退后再回报），单独捕获。
90	            ActionResult aResult = safeGet(fa);
91	            ActionResult bResult = safeGet(fb);
92	
93	            String finalStatus = service.get(id).status();
94	            // 唯一终态：只能是验证通过或窗口超期回退之一
95	            assertThat(finalStatus).isIn("VERIFIED", "WINDOW_EXPIRED");
96	
97	            boolean hasRollbackStep = repo.listSteps(id).stream()
98	                    .anyMatch(s -> "ROLLBACK".equals(s.getStepType()));
99	            boolean hasRollbackTrigger = service.events(id).stream()
100	                    .anyMatch(e -> "ROLLBACK_TRIGGER".equals(e.eventType()));
101	
102	            if ("VERIFIED".equals(finalStatus)) {
103	                // 验证先到达：不得产生任何回退痕迹
104	                assertThat(hasRollbackStep).isFalse();
105	                assertThat(hasRollbackTrigger).isFalse();
106	                // 封板必须成功
107	                ActionResult seal = service.seal(new SealRequest("c-seal", id));
108	                assertThat(seal.request().status()).isEqualTo("SEALED");
109	            } else {
110	                // 回退先到达：终态唯一，封板必须被拒绝
111	                assertThat(hasRollbackStep).isTrue();
112	                assertThat(hasRollbackTrigger).isTrue();
113	                assertThatThrownBySeal(id);
114	            }
115	            assertThat(bResult).isNotNull();
116	        } finally {
117	            pool.shutdownNow();
118	        }
119	    }
120	
121	    private static ActionResult safeGet(Future<Object> future) {
122	        try {
123	            return (ActionResult) future.get(30, TimeUnit.SECONDS);
124	        } catch (Exception e) {
125	            return null;
126	        }
127	    }
128	
129	    private void assertThatThrownBySeal(String id) {
130	        try {
131	            service.seal(new SealRequest("c-seal-fail", id));
132	            throw new AssertionError("回退终态后封板必须被拒绝");
133	        } catch (BusinessRuleException expected) {
134	            assertThat(expected.getMessage()).contains("终态唯一");
135	        }
136	    }
137	
138	    @Test
139	    @DisplayName("同键并发重放：两个线程用同一 requestUid 回报，恰好一次生效，另一次幂等返回")
140	    void concurrentSameKeyReportIsIdempotent() throws Exception {
141	        LocalDateTime end = BASE.plusHours(2);
142	        String id = "R-RACE-2";
143	        prepareExecuting(id, BASE, end, Priority.HIGH);
144	
145	        ExecutorService pool = Executors.newFixedThreadPool(2);
146	        CountDownLatch start = new CountDownLatch(1);
147	        try {
148	            StepReportRequest same = new StepReportRequest(
149	                    "same-uid-r1", id, 1, true, BASE.plusMinutes(5), null);
150	            List<Future<ActionResult>> futures = new java.util.ArrayList<>();
151	            for (int i = 0; i < 2; i++) {
152	                futures.add(pool.submit(() -> {
153	                    start.await();
154	                    return service.report(same);
155	                }));
156	            }
157	            start.countDown();
158	
159	            ActionResult first = futures.get(0).get(30, TimeUnit.SECONDS);
160	            ActionResult second = futures.get(1).get(30, TimeUnit.SECONDS);
161	
162	            long applied = java.util.stream.Stream.of(first, second)
163	                    .filter(r -> !r.replayed()).count();
164	            long replayed = java.util.stream.Stream.of(first, second)
165	                    .filter(ActionResult::replayed).count();
166	            assertThat(applied).as("恰好一次真正生效").isEqualTo(1);
167	            assertThat(replayed).as("另一次幂等重放").isEqualTo(1);
168	
169	            // 事件只落一条，步骤只有一条成功记录，无重复步骤
170	            List<CutoverEventPO> events = repo.listEvents(id).stream()
