package com.example.starter.cutover;

/**
 * 步骤回报/申请级事件类型。
 */
public enum EventType {
    /** 正常步骤回报 */
    STEP_REPORT,
    /** 回退指令命中记录 */
    ROLLBACK_TRIGGER,
    /** 封板后补报的迟到步骤 */
    LATE_REPORT,
    /** 封板事件 */
    SEAL,
